import { fileURLToPath } from 'node:url';
import { sql } from 'drizzle-orm';
import { readMigrationFiles } from 'drizzle-orm/migrator';
import { rowsOf } from './client.js';
import type { Db } from './client.js';

/** Folder holding the SQL migrations generated by `drizzle-kit generate`. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../drizzle', import.meta.url));

export interface MigrateResult {
  /** Number of migrations applied by this call. Zero when the database was up to date. */
  applied: number;
}

/**
 * Applies pending migrations. Works on any Drizzle PostgreSQL driver because it only uses the
 * public query API, and keeps the same bookkeeping table as Drizzle's own migrators
 * (`drizzle.__drizzle_migrations`), so the two stay interchangeable.
 *
 * Everything runs in one transaction behind an advisory lock: two processes starting at once
 * cannot both apply a migration, and a failing migration leaves the database unchanged.
 */
export async function migrate(db: Db): Promise<MigrateResult> {
  const migrations = readMigrationFiles({ migrationsFolder: MIGRATIONS_FOLDER });

  return db.transaction(async (tx) => {
    await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended('aab.migrate', 0))`);
    await tx.execute(sql`create schema if not exists drizzle`);
    await tx.execute(
      sql`create table if not exists drizzle.__drizzle_migrations (id serial primary key, hash text not null, created_at bigint)`,
    );

    const last = rowsOf(
      await tx.execute(
        sql`select created_at from drizzle.__drizzle_migrations order by created_at desc limit 1`,
      ),
    )[0];
    const lastAppliedAt = last === undefined ? null : Number(last.created_at);

    let applied = 0;
    for (const migration of migrations) {
      if (lastAppliedAt !== null && lastAppliedAt >= migration.folderMillis) continue;
      for (const statement of migration.sql) {
        if (statement.trim() === '') continue;
        await tx.execute(sql.raw(statement));
      }
      await tx.execute(
        sql`insert into drizzle.__drizzle_migrations (hash, created_at) values (${migration.hash}, ${migration.folderMillis})`,
      );
      applied += 1;
    }
    return { applied };
  });
}
